#!/usr/bin/env python3
import sys
import csv
import re
import math
import random
import os
from collections import defaultdict

def get_args(args, flags):
    res = {}
    for flag in flags:
        if flag in args:
            idx = args.index(flag)
            if idx + 1 < len(args):
                res[flag] = args[idx+1]
                args.pop(idx)
                args.pop(idx)
    return res, args

def has_flag(args, *flags):
    found = False
    for flag in flags:
        if flag in args:
            args.remove(flag)
            found = True
    return found, args

def get_flag_value(args, short, long, default=None):
    for flag in [short, long]:
        if flag in args:
            idx = args.index(flag)
            if idx + 1 < len(args):
                val = args[idx+1]
                args.pop(idx)
                args.pop(idx)
                return val, args
    return default, args

def parse_csv(file, delimiter=','):
    if file == '-':
        f = sys.stdin
    else:
        f = open(file, 'r', encoding='utf-8')
    reader = csv.reader(f, delimiter=delimiter)
    rows = list(reader)
    if file != '-':
        f.close()
    return rows

def write_csv(rows, out=None, delimiter=','):
    if out and out != '-':
        f = open(out, 'w', encoding='utf-8', newline='')
    else:
        f = sys.stdout
    writer = csv.writer(f, delimiter=delimiter)
    writer.writerows(rows)
    if out and out != '-':
        f.close()

def cmd_count(args):
    no_headers, args = has_flag(args, '-n', '--no-headers')
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    files = [a for a in args if not a.startswith('-')]
    if not files: files = ['-']
    for f in files:
        rows = parse_csv(f, delim)
        cnt = len(rows)
        if not no_headers and cnt > 0:
            cnt -= 1
        print(cnt)

def cmd_headers(args):
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    files = [a for a in args if not a.startswith('-')]
    if not files: files = ['-']
    for f in files:
        rows = parse_csv(f, delim)
        if not rows: continue
        headers = rows[0]
        max_len = len(str(len(headers)))
        for i, h in enumerate(headers):
            idx_str = str(i + 1)
            pad = max_len + 2 - len(idx_str)
            print(f"{idx_str}{' ' * pad}{h}")

def cmd_slice(args):
    start, args = get_flag_value(args, '-s', '--start')
    end, args = get_flag_value(args, '-e', '--end')
    no_headers, args = has_flag(args, '-n', '--no-headers')
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    files = [a for a in args if not a.startswith('-')]
    if not files: files = ['-']

    start = int(start) if start else 0
    end = int(end) if end else None

    for f in files:
        rows = parse_csv(f, delim)
        if not rows: continue
        header = []
        if not no_headers:
            header = rows[0]
            data = rows[1:]
        else:
            data = rows

        data = data[start:end]
        if header:
            data.insert(0, header)
        write_csv(data, delimiter=delim)

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("xsv is a suite of CSV command line utilities.")
        sys.exit(1)

    cmd = sys.argv[1]
    args = sys.argv[2:]

    if cmd == 'count': cmd_count(args)
    elif cmd == 'headers': cmd_headers(args)
    elif cmd == 'slice': cmd_slice(args)
