def get_args(args, flags):
    res = {}
    for flag in flags:
        if flag in args:
            idx = args.index(flag)
            if idx + 1 < len(args):
                res[flag] = args[idx+1]
                args.pop(idx)
                args.pop(idx)
    return res, args

def has_flag(args, *flags):
    found = False
    for flag in flags:
        if flag in args:
            args.remove(flag)
            found = True
    return found, args

def get_flag_value(args, short, long, default=None):
    for flag in [short, long]:
        if flag in args:
            idx = args.index(flag)
            if idx + 1 < len(args):
                val = args[idx+1]
                args.pop(idx)
                args.pop(idx)
