def parse_select(select_str, headers):
    invert = False
    if select_str.startswith('!'):
        invert = True
        select_str = select_str[1:]

    parts = select_str.split(',')
    selected_indices = []

    for p in parts:
        if '-' in p:
            s, e = p.split('-')
            s_idx = headers.index(s) if s in headers else int(s)-1
            e_idx = headers.index(e) if e in headers else int(e)-1
            selected_indices.extend(range(s_idx, e_idx + 1))
        elif p in headers:
            selected_indices.append(headers.index(p))
        elif p.isdigit():
            selected_indices.append(int(p)-1)

    if invert:
        res = [i for i in range(len(headers)) if i not in selected_indices]
    else:
        res = selected_indices
    return res

def cmd_select(args):
