        else:
            data = rows

        data = data[start:end]
        if header:
            data.insert(0, header)
        write_csv(data, delimiter=delim)

def parse_select(select_str, headers):
    invert = False
    if select_str.startswith('!'):
        invert = True
        select_str = select_str[1:]

    parts = select_str.split(',')
    selected_indices = []

    for p in parts:
        if '-' in p:
            s, e = p.split('-')
            s_idx = headers.index(s) if s in headers else int(s)-1
            e_idx = headers.index(e) if e in headers else int(e)-1
            selected_indices.extend(range(s_idx, e_idx + 1))
        elif p in headers:
            selected_indices.append(headers.index(p))
        elif p.isdigit():
            selected_indices.append(int(p)-1)

    if invert:
        res = [i for i in range(len(headers)) if i not in selected_indices]
    else:
        res = selected_indices
    return res

def cmd_select(args):
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    no_headers, args = has_flag(args, '-n', '--no-headers')
    if not args: return
    select_str = args[0]
    files = args[1:]
    if not files: files = ['-']

    for f in files:
        rows = parse_csv(f, delim)
        if not rows: continue
        headers = rows[0] if not no_headers else [str(i+1) for i in range(len(rows[0]))]
        indices = parse_select(select_str, headers)

        out_rows = []
        for r in rows:
            out_rows.append([r[i] for i in indices if i < len(r)])
        write_csv(out_rows, delimiter=delim)

def cmd_search(args):
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    select_col, args = get_flag_value(args, '-s', '--select')
    no_headers, args = has_flag(args, '-n', '--no-headers')
    if not args: return
    pattern = args[0]
    files = args[1:]
    if not files: files = ['-']

    import re
    regex = re.compile(pattern)

    for f in files:
        rows = parse_csv(f, delim)
        if not rows: continue

        headers = rows[0]
        if not no_headers:
            write_csv([headers], delimiter=delim)
            data = rows[1:]
        else:
            data = rows

        col_idx = -1
        if select_col:
            if select_col in headers:
                col_idx = headers.index(select_col)
            elif select_col.isdigit():
                col_idx = int(select_col) - 1

        out = []
        for r in data:
            match = False
            if col_idx >= 0 and col_idx < len(r):
                if regex.search(r[col_idx]): match = True
            else:
                for c in r:
                    if regex.search(c): match = True
            if match:
                out.append(r)
        if out: write_csv(out, delimiter=delim)

def cmd_cat(args):
    pad, args = has_flag(args, '-p', '--pad')
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    no_headers, args = has_flag(args, '-n', '--no-headers')

    if not args: return
    mode = args[0]
    files = args[1:]
    if not files: files = ['-']

    if mode == 'rows':
        first = True
        for f in files:
            rows = parse_csv(f, delim)
            if not rows: continue
            if first or no_headers:
                write_csv(rows, delimiter=delim)
                first = False
            else:
                write_csv(rows[1:], delimiter=delim)
    elif mode == 'columns':
        all_rows = [parse_csv(f, delim) for f in files]
        if not all_rows: return
        max_len = max(len(r) for r in all_rows)
        min_len = min(len(r) for r in all_rows)
        limit = max_len if pad else min_len

        out = []
        for i in range(limit):
            row = []
            for r in all_rows:
                if i < len(r):
                    row.extend(r[i])
                else:
                    row.extend([''] * (len(r[0]) if r else 0))
            out.append(row)
        write_csv(out, delimiter=delim)

def cmd_reverse(args):
    no_headers, args = has_flag(args, '-n', '--no-headers')
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    files = [a for a in args if not a.startswith('-')]
    if not files: files = ['-']

    for f in files:
        rows = parse_csv(f, delim)
        if not rows: continue
        if not no_headers:
            header = rows[0]
            data = rows[1:]
        else:
            header = None
            data = rows

        data.reverse()
        if header:
            data.insert(0, header)
        write_csv(data, delimiter=delim)

def cmd_flatten(args):
    no_headers, args = has_flag(args, '-n', '--no-headers')
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    files = [a for a in args if not a.startswith('-')]
    if not files: files = ['-']

    for f in files:
        rows = parse_csv(f, delim)
        if not rows: continue

        if not no_headers:
            headers = rows[0]
            data = rows[1:]
        else:
            headers = [str(i) for i in range(len(rows[0]))]
            data = rows

        max_len = max(len(h) for h in headers) if headers else 0

        for r in data:
            for i, val in enumerate(r):
                h = headers[i] if i < len(headers) else str(i)
                pad = max_len + 2 - len(h)
                print(f"{h}{' ' * pad}{val}")
            print("#")

def cmd_sort(args):
    no_headers, args = has_flag(args, '-n', '--no-headers')
    reverse, args = has_flag(args, '-R', '--reverse')
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    select_col, args = get_flag_value(args, '-s', '--select')

    files = [a for a in args if not a.startswith('-')]
    if not files: files = ['-']

    for f in files:
        rows = parse_csv(f, delim)
        if not rows: continue

        if not no_headers:
            headers = rows[0]
            data = rows[1:]
        else:
            headers = [str(i+1) for i in range(len(rows[0]))]
            data = rows

        col_idx = 0
        if select_col:
            if select_col in headers:
                col_idx = headers.index(select_col)
            elif select_col.isdigit():
                col_idx = int(select_col) - 1

        def get_val(r):
            if col_idx < len(r): return r[col_idx]
            return ""

        data.sort(key=get_val, reverse=reverse)
        if not no_headers:
            data.insert(0, headers)
        write_csv(data, delimiter=delim)

def cmd_table(args):
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    files = [a for a in args if not a.startswith('-')]
    if not files: files = ['-']

    for f in files:
        rows = parse_csv(f, delim)
        if not rows: continue

        col_widths = []
        for r in rows:
            for i, c in enumerate(r):
                if i >= len(col_widths):
                    col_widths.append(len(c))
                else:
                    col_widths[i] = max(col_widths[i], len(c))

        for r in rows:
            out = []
            for i, c in enumerate(r):
                if i == len(r) - 1:
                    out.append(c)
                else:
                    pad = col_widths[i] + 2 - len(c)
                    out.append(c + ' ' * pad)
            print("".join(out))

def cmd_frequency(args):
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    files = [a for a in args if not a.startswith('-')]
    if not files: files = ['-']

    for f in files:
        rows = parse_csv(f, delim)
        if not rows: continue
        headers = rows[0]
        data = rows[1:]

        freqs = [defaultdict(int) for _ in headers]
        for r in data:
            for i, c in enumerate(r):
                if i < len(freqs):
                    freqs[i][c] += 1

        out = [["field", "value", "count"]]
        for i, h in enumerate(headers):
            items = list(freqs[i].items())
            items.sort(key=lambda x: (-x[1], x[0]))
            for val, cnt in items:
                out.append([h, val, str(cnt)])
        write_csv(out, delimiter=delim)

def cmd_sample(args):
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    if not args: return
    n = int(args[0])
    files = args[1:]
    if not files: files = ['-']

    for f in files:
        rows = parse_csv(f, delim)
        if not rows: continue
        headers = rows[0]
        data = rows[1:]
        if len(data) > n:
            data = random.sample(data, n)
        data.insert(0, headers)
        write_csv(data, delimiter=delim)

def cmd_fixlengths(args):
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    files = [a for a in args if not a.startswith('-')]
    if not files: files = ['-']

    for f in files:
        rows = parse_csv(f, delim)
        if not rows: continue
        max_len = max(len(r) for r in rows)
        out = []
        for r in rows:
            if len(r) < max_len:
                out.append(r + [''] * (max_len - len(r)))
            else:
                out.append(r[:max_len])
        write_csv(out, delimiter=delim)

def cmd_fmt(args):
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    out_delim, args = get_flag_value(args, '-t', '--out-delimiter', ',')
    files = [a for a in args if not a.startswith('-')]
    if not files: files = ['-']

    for f in files:
        rows = parse_csv(f, delim)
        write_csv(rows, delimiter=out_delim)

def cmd_split(args):
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    size, args = get_flag_value(args, '-s', '--size', '500')
    size = int(size)
    if len(args) < 1: return
    outdir = args[0]
    files = args[1:]
    if not files: files = ['-']

    os.makedirs(outdir, exist_ok=True)

    for f in files:
        rows = parse_csv(f, delim)
        if not rows: continue
        headers = rows[0]
        data = rows[1:]

        for i in range(0, len(data), size):
            chunk = data[i:i+size]
            chunk.insert(0, headers)
            write_csv(chunk, out=os.path.join(outdir, f"{i//size}.csv"), delimiter=delim)

def cmd_partition(args):
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    if len(args) < 2: return
    col = args[0]
    outdir = args[1]
    files = args[2:]
    if not files: files = ['-']

    os.makedirs(outdir, exist_ok=True)

    for f in files:
        rows = parse_csv(f, delim)
        if not rows: continue
        headers = rows[0]
        data = rows[1:]

        idx = headers.index(col) if col in headers else 0
        parts = defaultdict(list)
        for r in data:
            if idx < len(r):
                parts[r[idx]].append(r)

        for k, part_rows in parts.items():
            part_rows.insert(0, headers)
            write_csv(part_rows, out=os.path.join(outdir, f"{k}.csv"), delimiter=delim)

def cmd_join(args):
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    if len(args) < 4: return
    col1 = args[0]
    file1 = args[1]
    col2 = args[2]
    file2 = args[3]

    rows1 = parse_csv(file1, delim)
    rows2 = parse_csv(file2, delim)
    if not rows1 or not rows2: return

    h1 = rows1[0]
    h2 = rows2[0]
    idx1 = h1.index(col1) if col1 in h1 else int(col1)-1
    idx2 = h2.index(col2) if col2 in h2 else int(col2)-1

    map2 = defaultdict(list)
    for r in rows2[1:]:
        if idx2 < len(r):
            map2[r[idx2]].append(r)

    out = [h1 + h2]
    for r in rows1[1:]:
        if idx1 < len(r):
            key = r[idx1]
            if key in map2:
                for r2 in map2[key]:
                    out.append(r + r2)
    write_csv(out, delimiter=delim)

def cmd_stats(args):
    delim, args = get_flag_value(args, '-d', '--delimiter', ',')
    files = [a for a in args if not a.startswith('-')]
    if not files: files = ['-']

    for f in files:
        rows = parse_csv(f, delim)
        if not rows: continue
        headers = rows[0]
        data = rows[1:]

        out = [["field","type","sum","min","max","min_length","max_length","mean","stddev"]]
        for i, h in enumerate(headers):
            vals = [r[i] for r in data if i < len(r)]
            vlen = [len(v) for v in vals]
            num_vals = []
            for v in vals:
                try: num_vals.append(float(v))
                except: pass

            if num_vals and len(num_vals) == len(vals):
                t = "Float" if any('.' in v for v in vals) else "Integer"
                s = sum(num_vals)
                mi = min(num_vals)
                ma = max(num_vals)
                mean = s / len(num_vals)
                stddev = math.sqrt(sum((x - mean)**2 for x in num_vals) / len(num_vals))
                out.append([h, t, str(int(s) if t=="Integer" else s), str(int(mi) if t=="Integer" else mi), str(int(ma) if t=="Integer" else ma), str(min(vlen)), str(max(vlen)), str(mean), str(stddev)])
            else:
                out.append([h, "String", "", min(vals) if vals else "", max(vals) if vals else "", str(min(vlen)) if vlen else "", str(max(vlen)) if vlen else "", "", ""])
        write_csv(out, delimiter=delim)

def cmd_index(args):
    files = [a for a in args if not a.startswith('-')]
    for f in files:
        if f != '-':
            with open(f + '.idx', 'wb') as out:
                out.write(b'\x00' * 32)

