import sys, csv, re, math, random, os
from collections import defaultdict

def get_args(args, flags):
    res = {}
    for flag in flags:
        if flag in args:
            idx = args.index(flag)
            if idx + 1 < len(args):
                res[flag] = args[idx+1]
                args.pop(idx); args.pop(idx)
    return res, args

def has_flag(args, *flags):
    found = False
    for flag in flags:
        if flag in args:
            args.remove(flag)
            found = True
    return found, args

def get_flag_value(args, short, long, default=None):
    for flag in [short, long]:
        if flag in args:
            idx = args.index(flag)
            if idx + 1 < len(args):
                val = args[idx+1]
                args.pop(idx); args.pop(idx)
                return val, args
    return default, args

def parse_csv(file, delimiter=','):
    f = sys.stdin if file == '-' else open(file, 'r', encoding='utf-8')
    reader = csv.reader(f, delimiter=delimiter)
    rows = list(reader)
    if file != '-': f.close()
    return rows

def write_csv(rows, out=None, delimiter=','):
    f = open(out, 'w', encoding='utf-8', newline='') if out and out != '-' else sys.stdout
    writer = csv.writer(f, delimiter=delimiter)
    writer.writerows(rows)
    if out and out != '-': f.close()

